import{_ as t,o as a,c as d,ag as s}from"./chunks/framework.C9sp7nFj.js";const E=JSON.parse('{"title":"MovJRel 关节插补相对偏移","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJRel.md","filePath":"3. 指令/1. 运动指令/MovJRel.md","lastUpdated":1778862643000}'),i={name:"3. 指令/1. 运动指令/MovJRel.md"};function o(n,e,r,l,c,h){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="movjrel-关节插补相对偏移" tabindex="-1">MovJRel 关节插补相对偏移 <a class="header-anchor" href="#movjrel-关节插补相对偏移" aria-label="Permalink to &quot;MovJRel 关节插补相对偏移&quot;">​</a></h1><p>MovJRel 为关节插补相对偏移指令。该指令以<strong>当前机器人位置</strong>或<strong>上一步运动指令的目标位置</strong>为起点，按指定的增量进行相对位移移动。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>与 <code>MovJ</code> 指令不同，<code>MovJRel</code> 的目标值无法通过示教直接获取。用户需事先在变量列表中新建**关节相对位置类型（DAPOS）**的变量。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJRel(P, [V], [B], [C], [PayLoad], [DO])</p><p>MovJRel(相对增量点, [速度], [平滑], [姿态], [负载], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>DAPOS 变量</td><td>执行该指令时机器人要移动的位置增量（各关节轴的偏移值）。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>用于指定机器人执行时的速度。SPEED 变量中的 <code>per</code> 分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式：<br><code>FINE</code>：无过渡。<br><code>RELATIVE</code>：相对过渡。<br><code>ABSOLUTE</code>：绝对过渡。<br><code>DEFAULT</code>：缺省类型。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后，可触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。目前支持的 IO 指令包括：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJRel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DAPOS0, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>机器人以 50 的速度运动到 P1 点，随后在 P1 点的基础上，使用 C100 中的过渡参数相对运动 <code>DAPOS0</code> 中的位移量，到达目标点。</p><p><strong>示例 2：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJRel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DAPOS0, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人以 50 的速度，从<strong>当前所在点</strong>直接相对运动 <code>DAPOS0</code> 中的位移量。</p>`,19)])])}const u=t(i,[["render",o]]);export{E as __pageData,u as default};
